import { useEffect, useState } from 'react'
import { Button } from '../../components/Button'
import { Card } from '../../components/Card'
import { Input } from '../../components/Input'
import { Modal } from '../../components/Modal'
import { StatusBadge } from '../../components/StatusBadge'
import { OperatorLayout } from '../../layouts/OperatorLayout'
import { awardVendorBid, createOperatorSlotRequest, getOperatorSlotRequests, type MarketplaceCategory, type SlotRequest } from '../../services/marketplaceService'

const categories: MarketplaceCategory[] = ['FLIGHT', 'HOTEL', 'ACTIVITY', 'TRANSFER']
const label = (value: string) => value[0] + value.slice(1).toLowerCase()

export function OperatorMarketplacePage() {
  const [requests, setRequests] = useState<SlotRequest[]>([]); const [modalOpen, setModalOpen] = useState(false); const [destination, setDestination] = useState(''); const [category, setCategory] = useState<MarketplaceCategory>('ACTIVITY'); const [dateNeeded, setDateNeeded] = useState(''); const [budgetCap, setBudgetCap] = useState(''); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const [saving, setSaving] = useState(false); const [awarding, setAwarding] = useState<string | null>(null)
  const load = async () => { try { setError(''); setRequests(await getOperatorSlotRequests()) } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load marketplace requests.') } }
  useEffect(() => { void load() }, [])
  const create = async () => { if (!destination.trim() || !dateNeeded || !Number.isFinite(Number(budgetCap)) || Number(budgetCap) <= 0) return setError('Enter a destination, date, and positive budget cap.')
    try { setSaving(true); setError(''); await createOperatorSlotRequest({ destination: destination.trim(), category, dateNeeded: new Date(dateNeeded).toISOString(), budgetCap: Number(budgetCap) }); setDestination(''); setDateNeeded(''); setBudgetCap(''); setModalOpen(false); setSuccess('Slot request published to matching vendors.'); await load() } catch (e) { setError(e instanceof Error ? e.message : 'Unable to create slot request.') } finally { setSaving(false) }
  }
  const award = async (request: SlotRequest, bidId: string) => { try { setAwarding(bidId); setError(''); await awardVendorBid(request.id, bidId); setSuccess('Bid awarded and inventory added to the shared inventory pool.'); await load() } catch (e) { setError(e instanceof Error ? e.message : 'Unable to award bid.') } finally { setAwarding(null) } }
  return <OperatorLayout><section className="operator-page"><header className="operator-page-heading"><div><p className="eyebrow">Vendor marketplace</p><h1>Source the right slot, competitively.</h1><p>Publish a need, compare incoming bids, and award a verified inventory item.</p></div><Button onClick={() => { setError(''); setModalOpen(true) }} type="button">Create slot request</Button></header>{error && <p className="auth-error" role="alert">{error}</p>}{success && <p className="auth-inline-message" role="status">{success}</p>}<div className="marketplace-request-grid">{requests.length === 0 && <Card><h2>No slot requests yet</h2><p className="page-copy">Create your first request to invite matching vendors to bid.</p></Card>}{requests.map((request) => <Card className="marketplace-request" key={request.id}><div className="marketplace-request-heading"><div><p className="eyebrow">{label(request.category)}</p><h2>{request.destination}</h2></div><StatusBadge status={request.status === 'AWARDED' ? 'confirmed' : request.status === 'CLOSED' ? 'cancelled' : 'pending'} /></div><div className="marketplace-meta"><span>Needed {new Date(request.dateNeeded).toLocaleDateString()}</span><strong>Budget cap ₹{request.budgetCap.toLocaleString()}</strong></div><div className="marketplace-bids"><h3>{request.bids?.length || 0} incoming bid{request.bids?.length === 1 ? '' : 's'}</h3>{!request.bids?.length && <p className="page-copy">Waiting for vendors to respond.</p>}{request.bids?.map((bid) => <div className="marketplace-bid" key={bid.id}><div><strong>{bid.vendor.name}</strong><span>{bid.notes || 'No note provided.'}</span></div><div><strong>₹{bid.price.toLocaleString()}</strong>{bid.status === 'PENDING' ? <Button disabled={Boolean(awarding)} onClick={() => void award(request, bid.id)} type="button">{awarding === bid.id ? 'Awarding…' : 'Award'}</Button> : <StatusBadge status={bid.status === 'ACCEPTED' ? 'confirmed' : 'cancelled'} />}</div></div>)}</div></Card>)}</div><Modal isOpen={modalOpen} onClose={() => !saving && setModalOpen(false)} title="Create slot request"><div className="marketplace-form"><Input label="Destination" placeholder="e.g. Delhi, India" value={destination} onChange={(e) => setDestination(e.target.value)} required /><label className="tp-input-wrap"><span className="tp-input-label">Category</span><select className="tp-input" value={category} onChange={(e) => setCategory(e.target.value as MarketplaceCategory)}>{categories.map((item) => <option key={item} value={item}>{label(item)}</option>)}</select></label><Input label="Date needed" type="date" value={dateNeeded} onChange={(e) => setDateNeeded(e.target.value)} required /><Input label="Budget cap" type="number" min="1" value={budgetCap} onChange={(e) => setBudgetCap(e.target.value)} required /><Button disabled={saving} onClick={() => void create()} type="button">{saving ? 'Publishing…' : 'Publish request'}</Button></div></Modal></section></OperatorLayout>
}
